ALTER TABLE news_posts ADD COLUMN related_team_id BIGINT UNSIGNED NULL AFTER tournament_id, ADD COLUMN related_match_id BIGINT UNSIGNED NULL AFTER related_team_id, ADD COLUMN is_featured TINYINT(1) NOT NULL DEFAULT 0 AFTER status, ADD COLUMN seo_title VARCHAR(180) NULL AFTER is_featured, ADD COLUMN seo_description VARCHAR(255) NULL AFTER seo_title, ADD FOREIGN KEY (related_team_id) REFERENCES teams(id) ON DELETE SET NULL, ADD FOREIGN KEY (related_match_id) REFERENCES matches(id) ON DELETE SET NULL;
ALTER TABLE galleries ADD COLUMN match_id BIGINT UNSIGNED NULL AFTER tournament_id, ADD COLUMN cover_item_id BIGINT UNSIGNED NULL AFTER match_id, ADD FOREIGN KEY (match_id) REFERENCES matches(id) ON DELETE SET NULL;
ALTER TABLE gallery_items ADD COLUMN credit VARCHAR(180) NULL AFTER caption, ADD COLUMN status VARCHAR(30) NOT NULL DEFAULT 'active' AFTER credit;
ALTER TABLE transfers ADD COLUMN movement_type VARCHAR(40) NOT NULL DEFAULT 'transfer' AFTER status, ADD COLUMN decision_reason TEXT NULL AFTER reason, ADD COLUMN decided_by BIGINT UNSIGNED NULL AFTER approved_at, ADD FOREIGN KEY (decided_by) REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE documents ADD COLUMN document_category VARCHAR(60) NULL AFTER title, ADD COLUMN starts_at DATETIME NULL AFTER visibility, ADD COLUMN ends_at DATETIME NULL AFTER starts_at;
ALTER TABLE export_jobs ADD COLUMN progress TINYINT UNSIGNED NOT NULL DEFAULT 0 AFTER status, ADD COLUMN expires_at DATETIME NULL AFTER completed_at;
